'use strict';
const games=[
 {id:'skyfall',title:'Skyfall Royale',genre:'Battle arena · 3D action',emoji:'🪂',art:'linear-gradient(130deg,#f6a64a,#3a77c5 58%,#253b6b)',desc:'Drop into a bright island, find gear and outlast the bots. A bite-sized, original battle royale.'},
 {id:'nightwatch',title:'Midnight at Freddy’s',genre:'Survival horror · 2D/3D',emoji:'🐻',art:'linear-gradient(130deg,#5e272d,#161a28 70%)',desc:'Keep watch over a quiet pizza place. Track the stage, manage your power, and make it to 6 AM.'},
 {id:'blockcraft',title:'Blocklands',genre:'Creative sandbox · 2D',emoji:'🧱',art:'linear-gradient(130deg,#61c5e1,#4f984f 55%,#83663c)',desc:'A tiny block-building world. Gather blocks, build a home, and make your own little landscape.'},
 {id:'poppy1',title:'Playtime: The Toy Factory',genre:'Puzzle adventure · 3D',emoji:'🧸',art:'linear-gradient(130deg,#13a6ac,#26426f)',desc:'Explore a colorful abandoned toy factory and solve clever room-sized puzzles.'},
 {id:'poppy2',title:'Playtime: The Train Yard',genre:'Puzzle adventure · 3D',emoji:'🚂',art:'linear-gradient(130deg,#e4a943,#315487)',desc:'A new chapter in the toy factory: explore the tracks, find clues, and open the way forward.'},
 {id:'poppy3',title:'Playtime: Deep Sleep',genre:'Puzzle adventure · 3D',emoji:'🌙',art:'linear-gradient(130deg,#5843a5,#112d55)',desc:'Venture deeper into the strange factory in this atmospheric original chapter.'},
 {id:'poppy4',title:'Playtime: The Safe Haven',genre:'Puzzle adventure · 3D',emoji:'🌀',art:'linear-gradient(130deg,#278d87,#263452)',desc:'Find a route through a twisting new section of the factory.'},
 {id:'poppy5',title:'Playtime: After Hours',genre:'Puzzle adventure · 3D',emoji:'🔦',art:'linear-gradient(130deg,#5d4ba0,#201a34)',desc:'A mysterious bonus chapter made for this virtual desktop.'},
 {id:'brick',title:'Brick by Brick',genre:'Creative building · 2D',emoji:'🧩',art:'linear-gradient(130deg,#e5b348,#cb6549)',desc:'Build cheerful little scenes with colorful toy bricks. No instructions required.'},
 {id:'caped',title:'City of Capes',genre:'Action adventure · 2D',emoji:'🦸',art:'linear-gradient(130deg,#583fa5,#1c3e69)',desc:'Swing through a neon city and leap over rooftop obstacles in this tiny superhero sprint.'},
 {id:'starcrew',title:'Star Crew',genre:'Social deduction · 2D',emoji:'🚀',art:'linear-gradient(130deg,#d75560,#2e204f)',desc:'A friendly crewmate puzzler: finish tasks, spot the sneaky bot, and keep the ship flying.'},
 {id:'mushroom',title:'Mushroom Kingdom Dash',genre:'Platformer · 2D',emoji:'🍄',art:'linear-gradient(130deg,#74c9ee,#42a95a 62%,#ddba59)',desc:'Run, jump and collect stars through a sunny, original side-scrolling platform world.'},
 {id:'crash',title:'Canyon Crasher',genre:'Platformer · 2D',emoji:'🦊',art:'linear-gradient(130deg,#efa64d,#a14c37 65%,#402747)',desc:'Dash across a colorful canyon, jump the gaps, and collect every shining fruit.'},
 {id:'pocket',title:'Pocket Pets',genre:'Cozy collection · 2D',emoji:'🐣',art:'linear-gradient(130deg,#ffcb81,#ef8ba5 70%,#965eab)',desc:'A cozy creature-collecting mini-game. Find friendly critters and fill your field guide.'},
 {id:'orbit',title:'Orbit Pinball',genre:'Arcade · 2D',emoji:'🪐',art:'linear-gradient(130deg,#69d8dc,#5245a4 55%,#22284e)',desc:'A quick, glowing pinball challenge. Tap to flip and keep the little planet in play.'},
 {id:'paint',title:'Pixel Painter',genre:'Creative · 2D',emoji:'🎨',art:'linear-gradient(130deg,#f47e87,#eab952 50%,#56b2a1)',desc:'Paint a tiny pixel-art picture on a friendly little canvas.'}
];
const state={installed:new Set(['skyfall','nightwatch','blockcraft']),windows:new Map(),active:null,z:10,steamTab:'store',steamFilter:'all',game:null,storage:[],filesPath:'C:\\',blenderShape:'cube',browserQuery:''};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const windows=$('#windows'),dialogLayer=$('#dialogLayer'),toastEl=$('#toast');
function toast(message){toastEl.textContent=message;toastEl.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>toastEl.classList.remove('show'),2200)}
function appIcon(app){return app==='steam'?'<span class="app-icon steam-icon">◉</span>':app==='blender'?'<span class="app-icon blender-icon">✿</span>':app==='browser'?'<span class="app-icon browser-icon"><b>G</b></span>':app==='files'?'<span class="app-icon folder-icon">📁</span>':'<span class="app-icon recycle-icon">♻</span>'}
function appName(app){return{steam:'Steam',blender:'Blender',browser:'Google',files:'File Explorer',recycle:'Recycle Bin',game:state.game?.title||'Game'}[app]||app}
function openApp(app){$('#startMenu').classList.add('hidden');if(state.windows.has(app)){const w=state.windows.get(app);w.classList.remove('minimized');focusWindow(w);return}const w=document.createElement('section');w.className='app-window '+(app==='blender'||app==='browser'||app==='files'?'':'');w.dataset.app=app;w.style.zIndex=++state.z;w.innerHTML=`<header class="titlebar">${appIcon(app)}<span class="titlebar-name">${appName(app)}</span><div class="window-controls"><button data-control="min" aria-label="Minimize">—</button><button data-control="max" aria-label="Maximize">□</button><button data-control="close" aria-label="Close">×</button></div></header><div class="window-content">${app==='steam'?steamMarkup():app==='blender'?blenderMarkup():app==='browser'?browserMarkup():app==='files'?filesMarkup():recycleMarkup()}</div>`;windows.append(w);state.windows.set(app,w);focusWindow(w);addTaskbar(app);wireWindow(w,app);if(app==='steam')renderSteam(w);if(app==='browser')wireBrowser(w);if(app==='files')wireFiles(w);if(app==='blender')wireBlender(w)}
function focusWindow(w){state.z++;w.style.zIndex=state.z;state.active=w;$$('.taskbar-app').forEach(b=>b.classList.toggle('active',b.dataset.app===w.dataset.app))}
function addTaskbar(app){const b=document.createElement('button');b.className='taskbar-app active';b.dataset.app=app;b.innerHTML=appIcon(app);b.onclick=()=>{const w=state.windows.get(app);if(w.classList.contains('minimized')){w.classList.remove('minimized');focusWindow(w)}else if(w===state.active){w.classList.add('minimized')}else focusWindow(w)};$('#taskbarApps').append(b)}
function closeApp(app){const w=state.windows.get(app);if(!w)return;if(app==='game'&&state.game){state.game.ended=true;cancelAnimationFrame(state.game.raf);state.game=null}w.remove();state.windows.delete(app);$(`.taskbar-app[data-app="${app}"]`)?.remove();state.active=null}
function wireWindow(w,app){w.addEventListener('pointerdown',()=>focusWindow(w));w.querySelectorAll('[data-control]').forEach(b=>b.onclick=e=>{e.stopPropagation();if(b.dataset.control==='close')closeApp(app);if(b.dataset.control==='min')w.classList.add('minimized');if(b.dataset.control==='max'){w.classList.toggle('maximized');if(w.classList.contains('maximized')){w.dataset.oldStyle=JSON.stringify({left:w.style.left,top:w.style.top,width:w.style.width,height:w.style.height,transform:w.style.transform});w.style.cssText+=';left:0;top:0;width:100%;height:100%;transform:none;border-radius:0'}else{w.style.cssText='';w.style.zIndex=++state.z}}});const bar=w.querySelector('.titlebar');let drag=null;bar.addEventListener('pointerdown',e=>{if(e.target.closest('.window-controls')||w.classList.contains('maximized'))return;drag={x:e.clientX,y:e.clientY,left:w.offsetLeft,top:w.offsetTop};bar.setPointerCapture(e.pointerId)});bar.addEventListener('pointermove',e=>{if(!drag)return;w.style.left=`${drag.left+e.clientX-drag.x}px`;w.style.top=`${drag.top+e.clientY-drag.y}px`;w.style.transform='none'});bar.addEventListener('pointerup',()=>drag=null)}
function steamMarkup(){return `<div class="steam-app"><header class="steam-top"><div class="steam-brand">STEAM<span>×</span></div><div class="steam-tabs"><button data-tab="store" class="selected">STORE</button><button data-tab="library">LIBRARY</button><button data-tab="community">COMMUNITY</button></div><div class="steam-user">☻　<b>PLAYER ONE</b>　⌄</div></header><div class="steam-layout"><aside class="steam-sidebar"><div class="side-label">YOUR STORE</div><button class="steam-side-btn selected" data-filter="all"><em>⌂</em>Featured</button><button class="steam-side-btn" data-filter="action"><em>⚔</em>Action</button><button class="steam-side-btn" data-filter="adventure"><em>✦</em>Adventure</button><button class="steam-side-btn" data-filter="creative"><em>▦</em>Creative</button><button class="steam-side-btn" data-filter="arcade"><em>◉</em>Arcade</button><div class="side-label" style="margin-top:15px">COLLECTIONS</div><button class="steam-side-btn" data-tab="library"><em>▣</em>Installed</button><button class="steam-side-btn" data-filter="all"><em>＋</em>All games</button><div class="side-label" style="margin-top:14px">PLAY YOUR WAY</div><button class="steam-side-btn" data-action="help"><em>⌨</em>Controls & help</button></aside><main class="steam-main"><div class="steam-toolbar"><h2 id="steamTitle">Featured & Recommended</h2><input class="steam-search" placeholder="⌕  Search games" aria-label="Search games"></div><div class="steam-view"></div></main></div></div>`}
function cardMarkup(g){const installed=state.installed.has(g.id);return `<article class="game-card" data-game="${g.id}"><div class="game-art" style="background:${g.art}"><span>${g.emoji}</span></div><div class="game-card-body"><h3>${g.title}</h3><p>${g.genre}</p><div class="game-card-foot"><span class="free-tag">FREE TO PLAY</span><button class="install-mini ${installed?'installed':''}" data-install="${g.id}">${installed?'▶ Play':'＋ Install'}</button></div></div></article>`}
function renderSteam(w){const view=w.querySelector('.steam-view');const search=w.querySelector('.steam-search');function render(){const q=search.value.trim().toLowerCase();const candidates=state.steamTab==='library'?games.filter(g=>state.installed.has(g.id)):games.filter(g=>state.steamFilter==='all'||g.genre.toLowerCase().includes(state.steamFilter));const filtered=candidates.filter(g=>!q||(g.title+' '+g.genre+' '+g.desc).toLowerCase().includes(q));if(state.steamTab==='library'){w.querySelector('#steamTitle').textContent='Your Library';view.innerHTML=`<div class="profile-strip">🎮　${state.installed.size} games in your library　·　All games are free in this virtual Steam.</div>${filtered.length?filtered.map(g=>`<div class="library-row"><div class="game-art" style="background:${g.art}"><span>${g.emoji}</span></div><div class="library-info"><h3>${g.title}</h3><p>${g.genre} · Ready to play</p></div><button class="install-button" data-play="${g.id}">▶ PLAY</button></div>`).join(''):'<div class="empty-search">No games found. Browse the Store to find something new.</div>'}`}else{w.querySelector('#steamTitle').textContent=state.steamFilter==='all'?'Featured & Recommended':`${state.steamFilter[0].toUpperCase()+state.steamFilter.slice(1)} games`;const feature=(!q&&state.steamFilter==='all')?`<section class="hero-card"><div class="hero-content"><div class="eyebrow">FREE · ORIGINAL MINI GAME</div><h2>Skyfall Royale</h2><p>A whole island. A handful of bots. One last player standing.</p><button class="primary-button" data-play="skyfall">${state.installed.has('skyfall')?'▶ PLAY NOW':'＋ ADD TO LIBRARY'}</button></div></section><h3 class="section-title">Explore the collection</h3>`:'';view.innerHTML=feature+(filtered.length?`<div class="game-grid">${filtered.map(cardMarkup).join('')}</div>`:'<div class="empty-search">No games match that search. Try another title.</div>')}}
search.addEventListener('input',render);w.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.steamTab=b.dataset.tab==='library'?'library':'store';state.steamFilter='all';w.querySelectorAll('.steam-tabs button').forEach(x=>x.classList.toggle('selected',x===b));w.querySelectorAll('.steam-side-btn').forEach(x=>x.classList.toggle('selected',x.dataset.tab===b.dataset.tab));render()});w.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.steamTab='store';state.steamFilter=b.dataset.filter;w.querySelectorAll('.steam-tabs button').forEach(x=>x.classList.toggle('selected',x.dataset.tab==='store'));w.querySelectorAll('.steam-side-btn').forEach(x=>x.classList.toggle('selected',x===b));render()});w.querySelector('[data-action=help]').onclick=()=>toast('WASD / arrows to move · Space to jump · click or tap to interact');view.addEventListener('click',e=>{const play=e.target.closest('[data-play]');if(play){if(!state.installed.has(play.dataset.play)){openInstall(play.dataset.play);return}launchGame(play.dataset.play);return}const install=e.target.closest('[data-install]');if(install){if(state.installed.has(install.dataset.install))launchGame(install.dataset.install);else openInstall(install.dataset.install);return}const card=e.target.closest('[data-game]');if(card)showGameInfo(card.dataset.game)});render()}

