w.addEventListener('click',e=>{const play=e.target.closest('[data-play]');if(play){if(!state.installed.has(play.dataset.play)){openInstall(play.dataset.play);return}launchGame(play.dataset.play);return}const install=e.target.closest('[data-install]');if(install){if(state.installed.has(install.dataset.install))launchGame(install.dataset.install);else openInstall(install.dataset.install);return}const card=e.target.closest('[data-game]');if(card)showGameInfo(card.dataset.game)});render()}
function showGameInfo(id){const g=games.find(x=>x.id===id);if(!g)return;showDialog(`<div class="eyebrow">${g.genre.toUpperCase()}</div><h2>${g.emoji}　${g.title}</h2><p>${g.desc}</p><p>Original, locally playable mini-game made for Steam × Windows. Free to play.</p>`,`<button class="secondary-button" data-dismiss>Close</button><button class="primary-button" data-gameaction="${id}">${state.installed.has(id)?'▶ Play':'＋ Install game'}</button>`);dialogLayer.querySelector('[data-gameaction]').onclick=()=>{closeDialog();if(state.installed.has(id))launchGame(id);else openInstall(id)}}
function showDialog(content,actions){dialogLayer.innerHTML=`<div class="dialog-backdrop"><section class="dialog">${content}<div class="dialog-actions">${actions}</div></section></div>`;dialogLayer.querySelector('.dialog-backdrop').onclick=e=>{if(e.target.classList.contains('dialog-backdrop'))closeDialog()};dialogLayer.querySelectorAll('[data-dismiss]').forEach(b=>b.onclick=closeDialog)}
function closeDialog(){dialogLayer.innerHTML=''}
function openInstall(id){const g=games.find(x=>x.id===id);if(!g)return;showDialog(`<div class="eyebrow">STEAM · VIRTUAL INSTALL</div><h2>Install ${g.title}?</h2><p>This game will be added to your virtual C: drive. Nothing is downloaded to your real device.</p><label class="drive-option"><input type="radio" checked name="drive"><span>💽 <b>C: Drive</b><small>Virtual storage · plenty of room</small></span></label>`,`<button class="secondary-button" data-dismiss>Cancel</button><button class="primary-button" id="confirmInstall">＋ Add to C: Drive</button>`);$('#confirmInstall').onclick=()=>{state.installed.add(id);saveState();closeDialog();toast(`${g.title} added to C: Drive`);const steam=state.windows.get('steam');if(steam)renderSteam(steam);setTimeout(()=>launchGame(id),300)}}
function saveState(){try{localStorage.setItem('pixelOS-installed',JSON.stringify([...state.installed]));localStorage.setItem('pixelOS-files',JSON.stringify(state.storage))}catch{}}
function loadState(){try{const saved=JSON.parse(localStorage.getItem('pixelOS-installed')||'[]');saved.forEach(x=>state.installed.add(x));state.storage=JSON.parse(localStorage.getItem('pixelOS-files')||'[]')}catch{}}
function launchGame(id){const game=games.find(g=>g.id===id);if(!game)return;closeApp('game');state.game={id,title:game.title,ended:false,score:0,health:100,raf:0,keys:{},time:0};const w=document.createElement('section');w.className='app-window game-window';w.dataset.app='game';w.style.zIndex=++state.z;w.innerHTML=`<header class="titlebar">${appIcon('steam')}<span class="titlebar-name">${game.title} — Steam Game</span><div class="window-controls"><button data-control="min">—</button><button data-control="max">□</button><button data-control="close">×</button></div></header><div class="window-content"><div class="game-shell"><div class="game-hud"><strong>${game.emoji} ${game.title}</strong><span id="gameStatus">${game.id==='nightwatch'?'12:00 AM · NIGHT 1':'❤️ 100'}</span><span class="hud-spacer"></span><button id="gamePause">Ⅱ Pause</button><button id="backSteam">◉ Steam</button></div><div class="game-stage"><canvas class="game-canvas"></canvas><div class="game-tip">${game.id==='skyfall'?'WASD / arrows move · click or Space shoot · collect ✚':game.id==='nightwatch'?'Check cameras, toggle doors and lights · survive until 6 AM':'WASD / arrows move · Space jump · click or tap to build'}</div><div class="mobile-controls"><div class="move-pad"><button class="up" data-key="ArrowUp">▲</button><button class="left" data-key="ArrowLeft">◀</button><button class="down" data-key="ArrowDown">▼</button><button class="right" data-key="ArrowRight">▶</button></div><button data-action="jump">⤒</button></div></div><footer class="game-bottom"><span>STEAM　⌂</span><span>Original mini-game · local play</span><span id="gameScore">SCORE 0</span></footer></div></div>`;windows.append(w);state.windows.set('game',w);focusWindow(w);addTaskbar('game');wireWindow(w,'game');wireGame(w,id)}

