function wireGame(w,id){const canvas=w.querySelector('canvas'),ctx=canvas.getContext('2d');const g=state.game;const stage=w.querySelector('.game-stage');let W=0,H=0,paused=false;const player={x:0,y:0,vx:0,vy:0,ground:true};const shots=[],foes=[],blocks=[];let last=0,worldOffset=0,night=0,power=100,cam='Stage',doors={left:false,right:false},lights={left:false,right:false};let cameraBox=null;function resize(){const r=stage.getBoundingClientRect();const d=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.floor(W*d);canvas.height=Math.floor(H*d);ctx.setTransform(d,0,0,d,0,0);if(!player.x)player.x=W*.48;if(!player.y)player.y=H*.65}new ResizeObserver(resize).observe(stage);resize();
