canvas.addEventListener('pointerdown',e=>{const r=canvas.getBoundingClientRect();shoot(e.clientX-r.left,e.clientY-r.top)});w.querySelectorAll('.mobile-controls [data-key]').forEach(b=>{const down=e=>{e.preventDefault();g.keys[b.dataset.key]=true},up=e=>{e.preventDefault();g.keys[b.dataset.key]=false};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('pointerleave',up)});w.querySelector('[data-action=jump]')?.addEventListener('pointerdown',()=>{if(player.ground){player.vy=-420;player.ground=false}});
